CREATE     PROCEDURE [synapse_fo].[usp_Insert_REVRECDEFERREDLINE]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:29:58
	Description: Insert stored procedure for REVRECDEFERREDLINE from synapse finops datalake to BI
*/
