		[AMOUNTINFUNCTIONALCURRENCY],
		[AMOUNTINREPORTINGCURRENCY],
		[COGSACCOUNT],
		[COMPANYCURRENCYCODE],
		[CREATEDBY],
		[CREATEDDATETIME],
