		[EXPECTEDPERIODNAME],
		[FileName],
		[INVENTDIMID],
		[INVENTTRANSID],
		[INVOICEDATE],
		[INVOICEID],
		[ITEMDESCRIPTION],
		[ITEMID],
		[JOURNALID],
		[LastProcessedChange_DateTime],
		[LATESTNEWVALUES],
		[LINEAMOUNT],
		[LINECOGSAMOUNT],
		[LINENUM],
