		[REMAININGCOGSAMOUNT],
		[REMAININGQTY],
		[REPORTINGEXCHRATE],
		[REVACCOUNT],
		[REVENUESCHEDULEID],
		[REVENUESCHEDULEIDDESCRIPTION],
		[SysRowId],
		[TOTALQTY]
	)
	SELECT 
