		stg.[INVENTTRANSID],
		stg.[INVOICEDATE],
		stg.[INVOICEID],
		stg.[ITEMDESCRIPTION],
		stg.[ITEMID],
		stg.[JOURNALID],
		stg.[LastProcessedChange_DateTime],
		stg.[LATESTNEWVALUES],
		stg.[LINEAMOUNT],
		stg.[LINECOGSAMOUNT],
		stg.[LINENUM],
		stg.[LSN],
		stg.[MODIFIEDBY],
		stg.[MODIFIEDDATETIME],
		stg.[MULTIPLEJOURNALS],
		stg.[ONHOLD],
