		stg.[RECOGNIZECOSTAMOUNT],
		stg.[RECOGNIZEDAMOUNT],
		stg.[RECOGNIZEDATE],
		stg.[RECOGNIZEDCOGSAMOUNT],
		stg.[RECOGNIZEDQTY],
		stg.[RECOGNIZENOWAMOUNT],
		stg.[RECOGNIZENOWCOGSAMOUNT],
		stg.[RECOGNIZENOWQTY],
