	FROM [staging_fo].[REVRECDEFERREDLINE] stg
		LEFT JOIN [synapse_fo].[REVRECDEFERREDLINE] tgt
			ON stg.[RECID] = tgt.[RECID] 
		
	WHERE tgt.[RECID] IS NULL
END
